<?php declare(strict_types=1);use App\Helpers\View;$e=static fn($v)=>View::e((string)$v);ob_start();?>
<div class="btp-shell"><header class="btp-banner"><div><small>Étape guidée</small><h1>Nouvelle FEB</h1><p>Choisissez d’abord le chantier pour charger ses lignes de déboursé validées.</p></div></header>
<section class="btp-panel"><form method="get" action="<?=$e(View::url('feb/nouvelle'))?>"><label>Chantier <select name="chantier" required onchange="this.form.submit()"><option value="">Sélectionner</option><?php foreach($chantiers as $c):?><option value="<?=$c['id']?>" <?=$selectedChantier===$c['id']?'selected':''?>><?=$e($c['code'].' · '.$c['nom'])?></option><?php endforeach;?></select></label></form></section>
<?php if($selectedChantier):?><section class="btp-panel"><form method="post" enctype="multipart/form-data" action="<?=$e(View::url('feb'))?>"><input type="hidden" name="_csrf_token" value="<?=$e($csrf)?>"><input type="hidden" name="chantier_id" value="<?=$selectedChantier?>"><div class="btp-form-grid"><label>Workflow<select name="workflow_id" required><?php foreach($workflows as $w):?><option value="<?=$w['id']?>"><?=$e($w['label'])?></option><?php endforeach;?></select></label><label>Type<select name="beneficiary_type"><option value="fournisseur">Fournisseur</option><option value="beneficiaire">Bénéficiaire</option></select></label><label>Fournisseur / bénéficiaire<input name="beneficiary_name" required maxlength="180"></label><label>Date du besoin<input type="date" name="needed_at" required></label><label>Détails bénéficiaire<input name="beneficiary_details" maxlength="500"></label><label>Justificatif (PDF/JPG/PNG/DOCX, 10 Mo)<input type="file" name="attachment" required></label></div><label>Motif<textarea name="purpose" required rows="3"></textarea></label>
<h2>Lignes de besoin</h2><div id="feb-lines"><?php for($n=0;$n<3;$n++):?><fieldset style="margin:1rem 0;padding:1rem;border:1px solid #dbe3ef"><legend>Ligne <?=$n+1?> <?=$n?'(facultative)':''?></legend><div class="btp-form-grid"><label>Déboursé<select name="lines[<?=$n?>][budget_line_id]" <?=$n?'':'required'?>><option value="">Sélectionner</option><?php foreach($lines as $l):?><option value="<?=$l['id']?>"><?=$e($l['description'])?> · <?=number_format((float)$l['total_cost'],0,',',' ')?> FCFA</option><?php endforeach;?></select></label><label>Description<input name="lines[<?=$n?>][description]" <?=$n?'':'required'?>></label><label>Quantité<input type="number" min="0.001" step="0.001" name="lines[<?=$n?>][quantity]" value="<?=$n?'':'1'?>"></label><label>Unité<input name="lines[<?=$n?>][unit]" value="u"></label><label>Prix unitaire<input type="number" min="0" step="0.01" name="lines[<?=$n?>][unit_amount]"></label></div></fieldset><?php endfor;?></div><button class="btp-primary" type="submit">Enregistrer le brouillon</button></form></section><?php endif;?></div>
